mapper.select:
SELECT device_code,pan,hor_offset as "horOffset",pitch_offset as "pitchOffset",real_hor_angle,real_pitch_angle FROM vm_device_ref_point_valid_t where device_code in
#{item}
and point_flag = '1' order by device_code asc

SELECT DISTINCT dev.id AS tagId, '101' AS tagClass, dev.tags_name, dev.latitude, dev.longitude, dev.tags_type, dev.tags_position, dev.resolutionx, dev.resolutiony, dev.coordinate FROM vm_ar_tags_info dev WHERE dev.delete_flag = 0 AND tag_class = '101'
AND dev.id IN
#{item}
AND ( ST_Contains(ST_PolygonFromText(CONCAT('POLYGON((',#{geoPointStr},'))')),POINT(dev.longitude, dev.latitude))> 0 OR ST_Touches(ST_PolygonFromText(CONCAT('POLYGON((',#{geoPointStr},'))')),POINT(dev.longitude,dev.latitude)) > 0 )
AND dev.ar_view_id = #{arViewId}
AND dev.channel_code = #{channelCode}
AND dev.tenant_id = #{tenantId}
AND dev.industry_code = #{industryCode}
${dataScope}

SELECT DISTINCT dev.id AS tagId, '102' AS tagClass, dev.tags_name, dev.latitude, dev.longitude, dev.tags_type, dev.device_code FROM vm_ar_tags_info dev WHERE dev.delete_flag = 0 AND tag_class = '102'
AND dev.id IN
#{item}
AND dev.longitude = #{longitude}
AND dev.latitude = #{latitude}
AND ( ST_Contains(ST_PolygonFromText(CONCAT('POLYGON((',#{geoPointStr},'))')),POINT(dev.longitude, dev.latitude))> 0 OR ST_Touches(ST_PolygonFromText(CONCAT('POLYGON((',#{geoPointStr},'))')),POINT(dev.longitude,dev.latitude)) > 0 )
AND dev.tenant_id = #{tenantId}
AND dev.industry_code = #{industryCode}
${dataScope}

SELECT DISTINCT dev.device_code AS tagId, '103' AS tagClass, ( CASE WHEN length( IFNULL( tdr.device_name, '' )) = 0 THEN dev.device_name ELSE tdr.device_name END ) AS tagsName, dev.latitude, dev.longitude FROM vm_device_info_t dev LEFT JOIN vm_order_devices t1 ON dev.device_code = t1.device_code LEFT JOIN vm_tenant_device_channel_rel_t tdr ON tdr.device_code = dev.device_code AND tdr.tenant_id = t1.tenant_id AND tdr.industry_code = t1.industry_code, vm_channel_info_t chan WHERE dev.device_code = chan.device_code AND chan.delete_flag = '0' AND t1.delete_flag = '0' AND dev.delete_flag = '0' AND t1.ord_status IN ( 0, 1, 2 )
AND dev.device_code IN
#{item}
AND dev.longitude = #{longitude}
AND dev.latitude = #{latitude}
AND ( ST_Contains(ST_PolygonFromText(CONCAT('POLYGON((',#{geoPointStr},'))')),POINT(dev.longitude, dev.latitude))> 0 OR ST_Touches(ST_PolygonFromText(CONCAT('POLYGON((',#{geoPointStr},'))')),POINT(dev.longitude,dev.latitude)) > 0 )
AND t1.tenant_id = #{tenantId}
AND t1.industry_code = #{industryCode}
${dataScope} ORDER BY height DESC, dev.device_status, dev.device_code

SELECT DISTINCT m.device_code as tagId, '105' as tagClass, ( CASE WHEN length( IFNULL( dr.device_name, '' )) = 0 THEN m.device_name ELSE dr.device_name END ) AS tagsName, m.latitude, m.longitude FROM vm_order_sensor_devices osd LEFT JOIN vm_iot_device_t m ON osd.device_code = m.device_code AND m.category_code = 2 AND m.delete_flag = 0 LEFT JOIN vm_tenant_iot_device_rel_t dr ON dr.device_code = m.device_code AND dr.tenant_id = osd.tenant_id AND dr.delete_flag = '0' AND dr.industry_code = osd.industry_code WHERE osd.delete_flag = 0 AND osd.ord_status IN ( 0, 1, 2 ) AND osd.category_code = 2 AND m.delete_flag = '0' AND m.device_status != 2
AND osd.device_code IN
#{item}
AND m.longitude = #{longitude}
AND m.latitude = #{latitude}
AND ( ST_Contains(ST_PolygonFromText(CONCAT('POLYGON((',#{geoPointStr},'))')),POINT(m.longitude, m.latitude))> 0 OR ST_Touches(ST_PolygonFromText(CONCAT('POLYGON((',#{geoPointStr},'))')),POINT(m.longitude,m.latitude)) > 0 )
AND osd.tenant_id = #{tenantId}
AND osd.industry_code = #{industryCode}
${dataScope}

SELECT DISTINCT dev.device_code AS tagId, '106' AS tagClass, ( CASE WHEN length( IFNULL( rel.device_name, '' )) = 0 THEN dev.device_name ELSE rel.device_name END ) AS tagsName, (case when length(IFNULL(nrel.device_name, '')) = 0 then nest.device_name else nrel.device_name end ) uavNestName, dev.latitude, dev.longitude FROM vm_uav_device_info_t dev LEFT JOIN vm_order_uav_devices t1 ON dev.device_code = t1.device_code LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = t1.device_code AND rel.tenant_id = t1.tenant_id AND rel.industry_code = t1.industry_code AND rel.delete_flag = '0' AND rel.device_type = 1 LEFT JOIN `vm_uav_nest_device_info` nest ON dev.uav_nest_code = nest.device_code LEFT JOIN vm_tenant_device_common_rel_t nrel ON nrel.device_code = nest.device_code AND nrel.industry_code = t1.industry_code AND nrel.tenant_id = t1.tenant_id AND nrel.delete_flag = '0' AND nrel.device_type = 4 WHERE t1.delete_flag = '0' AND dev.delete_flag = '0' AND t1.ord_status IN ( 0, 1, 2 )
AND dev.device_code IN
#{item}
AND dev.longitude = #{longitude}
AND dev.latitude = #{latitude}
AND ( ST_Contains(ST_PolygonFromText(CONCAT('POLYGON((',#{geoPointStr},'))')),POINT(dev.longitude, dev.latitude))> 0 OR ST_Touches(ST_PolygonFromText(CONCAT('POLYGON((',#{geoPointStr},'))')),POINT(dev.longitude,dev.latitude)) > 0 )
AND t1.tenant_id = #{tenantId}
AND t1.industry_code = #{industryCode}
${dataScope} ORDER BY dev.device_status, dev.device_code

SELECT m.device_code as tagId, '107' as tagClass, ( CASE WHEN length( IFNULL( dr.device_name, '' )) = 0 THEN m.device_name ELSE dr.device_name END ) AS tagsName, m.latitude, m.longitude FROM vm_order_sensor_devices osd LEFT JOIN vm_iot_device_t m ON osd.device_code = m.device_code AND m.category_code = 1 AND m.delete_flag = 0 LEFT JOIN vm_tenant_iot_device_rel_t dr ON dr.device_code = m.device_code AND dr.tenant_id = osd.tenant_id AND dr.delete_flag = '0' AND dr.industry_code = osd.industry_code WHERE osd.delete_flag = 0 AND osd.ord_status IN ( 0, 1, 2 ) AND osd.category_code = 1 AND m.delete_flag = '0' AND m.device_status != 2
AND osd.device_code IN
#{item}
AND m.longitude = #{longitude}
AND m.latitude = #{latitude}
AND ( ST_Contains(ST_PolygonFromText(CONCAT('POLYGON((',#{geoPointStr},'))')),POINT(m.longitude, m.latitude))> 0 OR ST_Touches(ST_PolygonFromText(CONCAT('POLYGON((',#{geoPointStr},'))')),POINT(m.longitude,m.latitude)) > 0 )
AND osd.tenant_id = #{tenantId}
AND osd.industry_code = #{industryCode}
${dataScope}

SELECT DISTINCT m.device_code as tagId, '108' as tagClass, ( CASE WHEN length( IFNULL( tdr.device_name, '' )) = 0 THEN m.device_name ELSE tdr.device_name END ) AS tagsName, m.latitude, m.longitude FROM vm_order_horn_devices osd LEFT JOIN vm_horn_device_info_t m ON osd.device_code = m.device_code LEFT JOIN vm_tenant_device_common_rel_t tdr ON tdr.device_code = osd.device_code AND tdr.tenant_id = osd.tenant_id AND tdr.industry_code = osd.industry_code AND tdr.delete_flag = 0 WHERE osd.delete_flag = '0' AND m.delete_flag = '0' AND m.device_status != 4 AND osd.ord_status IN ( 0, 1, 2 )
AND osd.device_code IN
#{item}
AND m.longitude = #{longitude}
AND m.latitude = #{latitude}
AND ( ST_Contains(ST_PolygonFromText(CONCAT('POLYGON((',#{geoPointStr},'))')),POINT(m.longitude, m.latitude))> 0 OR ST_Touches(ST_PolygonFromText(CONCAT('POLYGON((',#{geoPointStr},'))')),POINT(m.longitude,m.latitude)) > 0 )
AND osd.tenant_id = #{tenantId}
AND osd.industry_code = #{industryCode}
${dataScope} ORDER BY m.height + 0 DESC

SELECT polygon_id, feature_id, center_longitude, center_latitude, polygon_points_lon_lat, dataTable.layer_id, l.custom_name AS layerName, l.layer_type_id, t.type_name AS layerTypeName FROM vm_polygon_patch_config dataTable LEFT JOIN sys_layer l ON dataTable.layer_id = l.id LEFT JOIN sys_layer_type t ON l.layer_type_id = t.id WHERE dataTable.delete_flag = 0 ${dataScope}
AND dataTable.tenant_id = #{tenantId}
AND dataTable.industry_code = #{industryCode}
AND dataTable.device_code = #{deviceCode}
AND dataTable.channel_code = #{channelCode}
AND dataTable.layer_id = #{layerId}
AND dataTable.layer_id IN
#{item}
AND ( ST_Contains(ST_PolygonFromText(CONCAT('POLYGON((',#{geoPointStr},'))')),POINT(dataTable.center_longitude, dataTable.center_latitude))> 0 OR ST_Touches(ST_PolygonFromText(CONCAT('POLYGON((',#{geoPointStr},'))')),POINT(dataTable.center_longitude,dataTable.center_latitude)) > 0 )

SELECT DISTINCT l.id AS tagId, '104' AS tagClass, l.custom_name AS tagsName, maxx, maxy, minx, miny FROM sys_layer l WHERE l.delete_flag = 0
AND l.id IN
#{item}
${dataPermissions}
